test('OnCleanup also needs to be cleaned，', async () => {
  const spy1 = vi.fn()
  const spy2 = vi.fn()
  const num = ref(0)

  watch(num, (value, oldValue, onCleanup) => {
    if (value > 1) {
      return
    }
    spy1()
    onCleanup(() => {
      // OnCleanup also needs to be cleaned
      spy2()
    })
  })

  num.value++
  await nextTick()
  expect(spy1).toHaveBeenCalledTimes(1)
