import { computed, ref } from '@vue/reactivity'
import { watch } from '../src/apiWatch'

test('computed sync watcher order', () => {
  const n = ref(0)
  const compN = computed(() => n.value)
  const calls: number[] = []
  for (let i = 0; i < 5; i++) {
    watch(compN, () => calls.push(i), { flush: 'sync' })
  }
  n.value++
  expect(calls).toEqual([0, 1, 2, 3, 4])
})

